["Standar","Bagus"],["Modern","Berkualitas"],["Premium","Mewah"]]}$j$::jsonb; c jsonb; it jsonb; t int; k int; g int; ii int; b bigint; budgets bigint[] := array[500000,1000000,10000000,100000000]; req text[]; tags text[];
begin
perform setseed(0.7);
for c in select * from jsonb_array_elements(d->'cats') loop
  insert into categories(id,name,color,sort) values (c->>'id',c->>'n',c->>'c',(select count(*) from categories)) on conflict (id) do update set name=excluded.name,color=excluded.color;
  req := array(select jsonb_array_elements_text(c->'r'));
  for t in 0..3 loop
    b := budgets[t+1];
    for k in 0..1 loop
      tags := case when array_length(req,1)>3 then array(select x from unnest(req) x order by random() limit 3 + (t>=2)::int) else req end;
      insert into themes(id,category_id,budget,name,required_tags,difficulty)
      values (format('%s_%s_%s',c->>'id',t,k),c->>'id',b,c->'t'->t->>k,tags,t+1) on conflict (id) do nothing;
    end loop;
    ii := 0;
    for it in select * from jsonb_array_elements(c->'i') loop
      for g in 0..1 loop
        insert into items(id,category_id,budget,name,tag,price,quality,color,shape)
        values (format('%s_%s_%s_%s',c->>'id',t,ii,g), c->>'id', b,
          (it->>0)||' '||(d->'g'->t->>g), it->>1,
          greatest(1000, round(b*(it->>4)::numeric*(case when g=0 then 0.75 else 1.45 end)*(0.85+random()*0.3)::numeric, -3))::bigint,
          least(100, 30+t*15+g*15+floor(random()*11)::int-5), it->>3, it->>2) on conflict (id) do nothing;
      end loop;
      ii := ii + 1;
    end loop;
  end loop;
end loop;
insert into settings(key,value) values ('durations','[300,600,900,1200]') on conflict (key) do nothing;
end $$;
